mermaid.chartCode:
sequenceDiagram
 participant U as {{user}}
 participant P as ProxMenux
 participant R as {{registry}}
 participant X as Proxmox VE
 U->>P: {{update}}
 P->>R: {{resolve}}
 R-->>P: digest
 P->>P: {{verify}}
 P->>X: {{backup}}
 P->>X: {{import}}
 P->>X: {{reapply}}
 X-->>P: healthcheck
 alt {{healthy}}
  P-->>U: {{commit}}
 else {{failure}}
  P->>X: Rollback
  P-->>U: {{restored}}
 end
